// ---- ../../common/threefry2x32.js ----
// threefry2x32.js — JAX's threefry-2x32 block function, PRNGKey, split and 32-bit
// random bits, bit for bit, for every game whose reference draws from jax.random.
//
// Users: parity/craftax_classic (night static via threefryUniformF32, the
// per-step state_rng via split) and parity/chip8 (CXNN: split + randint uint8).
//
// What is mirrored, from jax/_src/prng.py with `jax_threefry_partitionable=True`
// (the default since jax 0.5; checked against 0.11.1 for craftax and 0.6.2 for
// chip8's oracle, identical bits):
//
//   * the Threefry-2x32 block function, 20 rounds, rotations
//     [13, 15, 26, 6] / [17, 29, 16, 24], key schedule ks = [k0, k1,
//     k0 ^ k1 ^ 0x1BD11BDA], injected every 4 rounds with the round-group
//     index added to the second word (`_threefry2x32_lowering`);
//   * the PARTITIONABLE counter layout: element i of the output array is
//     hashed with the 64-bit counter i split as (hi, lo) uint32 words
//     (`iota_2x32_shape`), and the two output words are XORed together
//     (`_threefry_random_bits_partitionable`, bit_width 32). The older
//     layout — halves of a flat iota, outputs concatenated — gives different
//     bits and is not what the installed JAX runs;
//   * split (`_threefry_split_foldlike`): output key j is the two words of
//     threefry(key, counter (0, j)).
//
// Pure uint32 work: `>>> 0` after every add, no BigInt, so V8 and QuickJS agree.

const THREEFRY_C240 = 0x1BD11BDA;

function _rotl32(x, r) {
  return ((x << r) | (x >>> (32 - r))) >>> 0;
}

// Scratch for the two output words, so the hot loop allocates nothing.
const _tfOut = new Uint32Array(2);

// Threefry-2x32 of counter (x0, x1) under key (k0, k1). Result in _tfOut.
function _threefry2x32(k0, k1, x0, x1) {
  const ks0 = k0 >>> 0, ks1 = k1 >>> 0;
  const ks2 = (ks0 ^ ks1 ^ THREEFRY_C240) >>> 0;
  let v0 = (x0 + ks0) >>> 0;
  let v1 = (x1 + ks1) >>> 0;

  // Four rounds with rotations R, then a key injection.
  // apply_round: v0 += v1; v1 = rotl(v1, r); v1 ^= v0.
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 13); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 15); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 26); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 6);  v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + ks1) >>> 0; v1 = (v1 + ks2 + 1) >>> 0;

  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 17); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 29); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 16); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 24); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + ks2) >>> 0; v1 = (v1 + ks0 + 2) >>> 0;

  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 13); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 15); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 26); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 6);  v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + ks0) >>> 0; v1 = (v1 + ks1 + 3) >>> 0;

  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 17); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 29); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 16); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 24); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + ks1) >>> 0; v1 = (v1 + ks2 + 4) >>> 0;

  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 13); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 15); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 26); v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + v1) >>> 0; v1 = _rotl32(v1, 6);  v1 = (v0 ^ v1) >>> 0;
  v0 = (v0 + ks2) >>> 0; v1 = (v1 + ks0 + 5) >>> 0;

  _tfOut[0] = v0;
  _tfOut[1] = v1;
}

// jax.random.bits(key, (n,), uint32) under the partitionable layout: element
// i is threefry(key, hi(i), lo(i)) with the two words XORed. n < 2^32 here,
// so the high counter word is always 0.
function threefryRandomBits32(k0, k1, i) {
  _threefry2x32(k0, k1, 0, i >>> 0);
  return (_tfOut[0] ^ _tfOut[1]) >>> 0;
}

// jax.random.PRNGKey(seed) for a 32-bit seed: `_threefry_seed` puts the
// seed's high 32 bits in the first word and the low 32 in the second, so a
// seed below 2^32 is [0, seed].
function threefryPRNGKey(seed) {
  return [0, seed >>> 0];
}

// jax.random.split(key) under the partitionable layout
// (`_threefry_split_foldlike`): output key j is the two words of
// threefry(key, counter (0, j)). Writes [a0, a1, b0, b1] into out, where
// [a0, a1] is split(key)[0] and [b0, b1] is split(key)[1].
function threefrySplit(k0, k1, out) {
  _threefry2x32(k0, k1, 0, 0);
  out[0] = _tfOut[0]; out[1] = _tfOut[1];
  _threefry2x32(k0, k1, 0, 1);
  out[2] = _tfOut[0]; out[3] = _tfOut[1];
  return out;
}

// ---- src/10_threefry.js ----
// ---- CXNN's random byte: jax.random.randint(subkey, (), 0, 256, uint8) ----
// Octax draws CXNN as `key, subkey = split(state.rng); randint(subkey, (), 0, 256, uint8)`
// (octax/instructions/memory.py execute_random). The threefry block function, PRNGKey,
// split and 32-bit bits are the shared ../../common/threefry2x32.js (bundled before this
// file). Mirrored from jax 0.6.2, jax_threefry_partitionable=True (the oracle venv):
//   * bits (prng.py _threefry_random_bits_partitionable): scalar shape -> counter (0, 0),
//     the two output words XORed, truncated to the dtype;
//   * randint (random.py _randint) with maxval 256 out of range for uint8: span wraps to 0,
//     XLA's rem-by-zero returns the dividend, the multiplier becomes 0, and the result is
//     `lower_bits` alone, i.e. the low 8 bits of bits(split(subkey)[1]).
// Checked: G1 (11 CXNN vectors from Octax's tests) and G2 (10k keys, tests/test_threefry.py).

const c8SplitTmp = new Uint32Array(4);

// jax.random.bits(key, (), uint32): counter (0, 0), words XORed.
function c8ThreefryBits32(k0, k1) {
  return threefryRandomBits32(k0, k1, 0);
}

// jax.random.randint(key, (), 0, 256, uint8): the low byte of bits(split(key)[1]).
function c8Randint8(k0, k1) {
  threefrySplit(k0, k1, c8SplitTmp);
  return c8ThreefryBits32(c8SplitTmp[2], c8SplitTmp[3]) & 0xFF;
}

// ---- src/20_cpu.js ----
// ---- CHIP-8 CPU with Octax's exact semantics ----
// Reference: octax/emulator.py (fetch, execute), octax/instructions/*.py, octax/stack.py,
// octax/state.py at the commit pinned in manifest.json. Every quirk below is the reference's
// (see PLAN.md section 2 and manifest.json reference_quirks); do not "fix" any of it.
//
// Integer-only: typed-array state, `& 0xFFFF` / `& 0xFF` where JAX's dtypes wrap, JAX's
// index rules made explicit: a gather (read) normalises a negative index once by adding
// the size and then clamps into range; a scatter (write) normalises once and drops an index
// still out of range. `sp` is a plain integer because Octax's stack pointer is an unbounded
// int32 (-1 after a pop on empty, 17 after a 17th push).

const C8_MEM = 4096, C8_W = 64, C8_H = 32, C8_STACK = 16;
const C8_FONT_START = 0x50, C8_PROGRAM_START = 0x200;
const C8_FONT = [
  0xF0, 0x90, 0x90, 0x90, 0xF0,  0x20, 0x60, 0x20, 0x20, 0x70,
  0xF0, 0x10, 0xF0, 0x80, 0xF0,  0xF0, 0x10, 0xF0, 0x10, 0xF0,
  0x90, 0x90, 0xF0, 0x10, 0x10,  0xF0, 0x80, 0xF0, 0x10, 0xF0,
  0xF0, 0x80, 0xF0, 0x90, 0xF0,  0xF0, 0x10, 0x20, 0x40, 0x40,
  0xF0, 0x90, 0xF0, 0x90, 0xF0,  0xF0, 0x90, 0xF0, 0x10, 0xF0,
  0xF0, 0x90, 0xF0, 0x90, 0x90,  0xE0, 0x90, 0xE0, 0x90, 0xE0,
  0xF0, 0x80, 0x80, 0x80, 0xF0,  0xE0, 0x90, 0x90, 0x90, 0xE0,
  0xF0, 0x80, 0xF0, 0x80, 0xF0,  0xF0, 0x80, 0xF0, 0x80, 0x80,
];

// display[x * 32 + y] mirrors Octax's (64, 32) bool array in C order, so a byte-packing of
// this array in index order is the same bytes the oracle hashes.
function c8Create() {
  return {
    mem: new Uint8Array(C8_MEM),
    V: new Uint8Array(16),
    I: 0, pc: C8_PROGRAM_START,
    stack: new Uint16Array(C8_STACK), sp: 0,
    delay: 0, sound: 0,
    keypad: new Uint8Array(16),
    display: new Uint8Array(C8_W * C8_H),
    rng: new Uint32Array(2),
    modern: true,
  };
}

// octax.create_state(rng): zero everything, font at 0x50, pc 0x200.
function c8Reset(cpu, rng0, rng1) {
  cpu.mem.fill(0);
  for (let i = 0; i < C8_FONT.length; i++) cpu.mem[C8_FONT_START + i] = C8_FONT[i];
  cpu.V.fill(0); cpu.I = 0; cpu.pc = C8_PROGRAM_START;
  cpu.stack.fill(0); cpu.sp = 0;
  cpu.delay = 0; cpu.sound = 0;
  cpu.keypad.fill(0); cpu.display.fill(0);
  cpu.rng[0] = rng0 >>> 0; cpu.rng[1] = rng1 >>> 0;
  return cpu;
}

function c8LoadRom(cpu, bytes) {
  for (let i = 0; i < bytes.length && C8_PROGRAM_START + i < C8_MEM; i++) cpu.mem[C8_PROGRAM_START + i] = bytes[i];
}

// JAX gather index rule for an array of size n.
function c8GatherIdx(i, n) {
  if (i < 0) i += n;
  return i < 0 ? 0 : (i >= n ? n - 1 : i);
}

// JAX scatter index rule: the normalised index, or -1 when the write is dropped.
function c8ScatterIdx(i, n) {
  if (i < 0) i += n;
  return (i < 0 || i >= n) ? -1 : i;
}

// octax.emulator.fetch: two clamped reads, pc + 2 in uint16.
function c8Fetch(cpu) {
  const hi = cpu.mem[c8GatherIdx(cpu.pc, C8_MEM)];
  const lo = cpu.mem[c8GatherIdx((cpu.pc + 1) & 0xFFFF, C8_MEM)];
  cpu.pc = (cpu.pc + 2) & 0xFFFF;
  return ((hi << 8) | lo) >>> 0;
}

// octax/stack.py push: address & 0xFFF, scatter at sp, sp + 1.
function c8Push(cpu, address) {
  const i = c8ScatterIdx(cpu.sp, C8_STACK);
  if (i >= 0) cpu.stack[i] = address & 0xFFF;
  cpu.sp += 1;
}

// octax/stack.py pop: sp - 1, gather, zero that slot.
function c8Pop(cpu) {
  cpu.sp -= 1;
  const address = cpu.stack[c8GatherIdx(cpu.sp, C8_STACK)];
  const i = c8ScatterIdx(cpu.sp, C8_STACK);
  if (i >= 0) cpu.stack[i] = 0;
  return address;
}

// 0NNN: only 00E0 and 00EE do anything (system.py).
function c8OpSystem(cpu, ins) {
  if (ins === 0x00E0) cpu.display.fill(0);
  else if (ins === 0x00EE) cpu.pc = c8Pop(cpu);
}

// 8XYN (alu.py execute_alu_operation): VX := result, then VF := flag, for EVERY N.
function c8OpAlu(cpu, x, y, n) {
  const V = cpu.V;
  const vx = V[x], vy = V[y];
  let result = vx, vf = 0;
  switch (n) {
    case 0x0: result = vy; break;
    case 0x1: result = vx | vy; break;
    case 0x2: result = vx & vy; break;
    case 0x3: result = vx ^ vy; break;
    case 0x4: { const s = vx + vy; result = s & 0xFF; vf = s > 255 ? 1 : 0; break; }
    case 0x5: result = (vx - vy) & 0xFF; vf = vx >= vy ? 1 : 0; break;
    case 0x6: { const v = cpu.modern ? vx : vy; result = v >> 1; vf = v & 1; break; }
    case 0x7: result = (vy - vx) & 0xFF; vf = vy >= vx ? 1 : 0; break;
    case 0xE: { const v = cpu.modern ? vx : vy; result = (v << 1) & 0xFF; vf = (v & 0x80) >> 7; break; }
    default: break;                       // undefined N: VX unchanged, VF := 0
  }
  V[x] = result;
  V[0xF] = vf;
}

// DXYN (display.py): start wraps, sprite clips, VF = any pixel that was on under a set bit.
function c8OpDraw(cpu, x, y, n) {
  const sx = cpu.V[x] % C8_W, sy = cpu.V[y] % C8_H;
  const d = cpu.display;
  let collision = 0;
  for (let row = 0; row < n; row++) {
    const py = sy + row;
    if (py >= C8_H) break;
    const byte = cpu.mem[c8GatherIdx(cpu.I + row, C8_MEM)];
    for (let col = 0; col < 8; col++) {
      const px = sx + col;
      if (px >= C8_W) break;
      if ((byte >> (7 - col)) & 1) {
        const k = px * C8_H + py;
        if (d[k]) collision = 1;
        d[k] ^= 1;
      }
    }
  }
  cpu.V[0xF] = collision;
}

// FXNN (misc.py execute_misc_instruction); anything not listed is a no-op.
function c8OpMisc(cpu, x, nn) {
  const V = cpu.V;
  switch (nn) {
    case 0x07: V[x] = cpu.delay; break;
    case 0x0A: {                            // wait for key: rewind until any key, then lowest index
      let k = -1;
      for (let i = 0; i < 16; i++) if (cpu.keypad[i]) { k = i; break; }
      if (k >= 0) V[x] = k; else cpu.pc = (cpu.pc - 2) & 0xFFFF;
      break;
    }
    case 0x15: cpu.delay = V[x]; break;
    case 0x18: cpu.sound = V[x]; break;
    case 0x1E: {                            // I + VX in uint16; VF on > 0xFFF; I masked
      const s = (cpu.I + V[x]) & 0xFFFF;
      V[0xF] = s > 0xFFF ? 1 : 0;
      cpu.I = s & 0xFFF;
      break;
    }
    case 0x29: cpu.I = (C8_FONT_START + ((V[x] * 5) & 0xFF)) & 0xFF; break;   // all uint8
    case 0x33: {
      const v = V[x];
      const digits = [Math.floor(v / 100), Math.floor(v / 10) % 10, v % 10];
      for (let i = 0; i < 3; i++) { const a = c8ScatterIdx(cpu.I + i, C8_MEM); if (a >= 0) cpu.mem[a] = digits[i]; }
      break;
    }
    case 0x55: {
      for (let i = 0; i <= x; i++) { const a = c8ScatterIdx(cpu.I + i, C8_MEM); if (a >= 0) cpu.mem[a] = V[i]; }
      if (!cpu.modern) cpu.I = (cpu.I + x + 1) & 0xFFFF;
      break;
    }
    case 0x65: {
      for (let i = 0; i <= x; i++) V[i] = cpu.mem[c8GatherIdx(cpu.I + i, C8_MEM)];
      if (!cpu.modern) cpu.I = (cpu.I + x + 1) & 0xFFFF;
      break;
    }
    default: break;
  }
}

// octax.emulator.execute(state, instruction)
function c8Execute(cpu, ins) {
  const op = (ins & 0xF000) >> 12;
  const x = (ins & 0x0F00) >> 8;
  const y = (ins & 0x00F0) >> 4;
  const n = ins & 0x000F;
  const nn = ins & 0x00FF;
  const nnn = ins & 0x0FFF;
  const V = cpu.V;
  switch (op) {
    case 0x0: c8OpSystem(cpu, ins); break;
    case 0x1: cpu.pc = nnn; break;
    case 0x2: c8Push(cpu, cpu.pc); cpu.pc = nnn; break;
    case 0x3: if (V[x] === nn) cpu.pc = (cpu.pc + 2) & 0xFFFF; break;
    case 0x4: if (V[x] !== nn) cpu.pc = (cpu.pc + 2) & 0xFFFF; break;
    case 0x5: if (V[x] === V[y]) cpu.pc = (cpu.pc + 2) & 0xFFFF; break;   // any 5XYN
    case 0x6: V[x] = nn; break;
    case 0x7: V[x] = (V[x] + nn) & 0xFF; break;
    case 0x8: c8OpAlu(cpu, x, y, n); break;
    case 0x9: if (V[x] !== V[y]) cpu.pc = (cpu.pc + 2) & 0xFFFF; break;   // any 9XYN
    case 0xA: cpu.I = nnn; break;
    case 0xB: cpu.pc = cpu.modern ? ((nn + V[x]) & 0xFFF) : ((nnn + V[0]) & 0xFFF); break;
    case 0xC: {                            // key, subkey = split(rng); VX = randint(subkey) & NN
      threefrySplit(cpu.rng[0], cpu.rng[1], c8SplitTmp);
      const k0 = c8SplitTmp[0], k1 = c8SplitTmp[1];
      V[x] = c8Randint8(c8SplitTmp[2], c8SplitTmp[3]) & nn;
      cpu.rng[0] = k0; cpu.rng[1] = k1;
      break;
    }
    case 0xD: c8OpDraw(cpu, x, y, n); break;
    case 0xE: {                            // EX9E unless NN == A1 (control_flow.py)
      const pressed = cpu.keypad[V[x] & 0xF] ? 1 : 0;
      if (pressed ^ (nn === 0xA1 ? 1 : 0)) cpu.pc = (cpu.pc + 2) & 0xFFFF;
      break;
    }
    case 0xF: c8OpMisc(cpu, x, nn); break;
    default: break;
  }
}

// One instruction: fetch then execute (octax.env.run_instruction).
function c8Step(cpu) {
  c8Execute(cpu, c8Fetch(cpu));
}

// The display as 256 packed bytes in index order (what the oracle sha1s), hex.
function c8DisplayHex(cpu) {
  let s = '';
  const d = cpu.display;
  for (let i = 0; i < d.length; i += 8) {
    let b = 0;
    for (let j = 0; j < 8; j++) b = (b << 1) | d[i + j];
    s += (b < 16 ? '0' : '') + b.toString(16);
  }
  return s;
}

// ---- src/30_env.js ----
// ---- Octax's OctaxEnv on the CPU: reset, step, score, terminated ----
// Reference: octax/env.py (_reset, reset, step) constructed as octax/environments/__init__.py
// create_environment does. One env step = press action_set[a] (a == len(action_set) is NOOP),
// run (700 // 60) * 4 = 44 instructions, apply the timer rule, release the key, then
// score / reward / terminated / truncated. See PLAN.md section 2.
//
// Game definitions (games/<game>.json) carry score and terminated as small JSON expression
// trees over the registers, transcribed from the module's score_fn / terminated_fn. c8Eval
// follows JAX's dtype rules so a uint8 expression wraps where Octax's does: V is uint8,
// consts are weakly typed, an explicit {"op":"i32"} node promotes; u8 (op) u8 -> u8 wrap,
// anything with i32 -> i32; comparisons and or/and are bool; cond picks by a bool.

const C8_INSTRUCTIONS_PER_STEP = Math.floor(700 / 60);      // 11
const C8_FRAME_SKIP = 4;
const C8_INSTRUCTIONS_PER_ENV_STEP = C8_INSTRUCTIONS_PER_STEP * C8_FRAME_SKIP;   // 44
const C8_MAX_STEPS = 4500;

function c8EvalType(a, b) {
  if (a === 'i32' || b === 'i32') return 'i32';
  if (a === 'u8' || b === 'u8') return 'u8';
  return 'weak';
}

function c8Wrap(v, t) {
  if (t === 'u8') return ((v % 256) + 256) % 256;
  if (t === 'i32') return v | 0;
  return v;
}

// Python / JAX floor division and remainder (result takes the divisor's sign).
function c8FloorDiv(a, b) { return Math.floor(a / b); }
function c8Mod(a, b) { return a - b * Math.floor(a / b); }

// Returns {v, t}; t in 'u8' | 'i32' | 'weak' | 'bool'.
function c8Eval(node, cpu) {
  switch (node.op) {
    case 'V': return { v: cpu.V[node.i], t: 'u8' };
    case 'const': return { v: node.v, t: 'weak' };
    case 'i32': return { v: c8Eval(node.a, cpu).v | 0, t: 'i32' };
    case 'u8': return { v: c8Wrap(c8Eval(node.a, cpu).v, 'u8'), t: 'u8' };
    case 'neg': { const a = c8Eval(node.a, cpu); return { v: c8Wrap(-a.v, a.t), t: a.t }; }
    case 'add': case 'sub': case 'mul': case 'floordiv': case 'mod': {
      const a = c8Eval(node.a, cpu), b = c8Eval(node.b, cpu);
      const t = c8EvalType(a.t, b.t);
      let v;
      if (node.op === 'add') v = a.v + b.v;
      else if (node.op === 'sub') v = a.v - b.v;
      else if (node.op === 'mul') v = a.v * b.v;
      else if (node.op === 'floordiv') v = c8FloorDiv(a.v, b.v);
      else v = c8Mod(a.v, b.v);
      return { v: c8Wrap(v, t), t };
    }
    case 'eq': case 'ne': case 'gt': case 'lt': case 'ge': case 'le': {
      const a = c8Eval(node.a, cpu).v, b = c8Eval(node.b, cpu).v;
      const r = node.op === 'eq' ? a === b : node.op === 'ne' ? a !== b : node.op === 'gt' ? a > b
        : node.op === 'lt' ? a < b : node.op === 'ge' ? a >= b : a <= b;
      return { v: r ? 1 : 0, t: 'bool' };
    }
    case 'or': return { v: (c8Eval(node.a, cpu).v || c8Eval(node.b, cpu).v) ? 1 : 0, t: 'bool' };
    case 'and': return { v: (c8Eval(node.a, cpu).v && c8Eval(node.b, cpu).v) ? 1 : 0, t: 'bool' };
    case 'not': return { v: c8Eval(node.a, cpu).v ? 0 : 1, t: 'bool' };
    case 'cond': return c8Eval(node.c, cpu).v ? c8Eval(node.a, cpu) : c8Eval(node.b, cpu);
    case 'false': return { v: 0, t: 'bool' };
    case 'true': return { v: 1, t: 'bool' };
    default: throw new Error('c8Eval: unknown op ' + node.op);
  }
}

function c8EnvCreate(def, romBytes) {
  return {
    def, rom: romBytes,
    cpu: c8Create(),
    actionSet: def.action_set.slice(),
    numActions: def.action_set.length + 1,
    noop: def.action_set.length,
    disableDelay: !!def.disable_delay,
    maxSteps: C8_MAX_STEPS,
    time: 0, score: 0, previousScore: 0, reward: 0, terminated: false, truncated: false,
    startup: null,                       // cached post-startup CPU (Octax's cached_reset_state)
  };
}

// The games' custom_startup functions, transcribed from octax/environments/<game>.py: hold one key
// while running N instructions on the fresh state, then release it.
function c8StartupHoldKey(cpu, key, n) {
  cpu.keypad[key] = 1;
  for (let i = 0; i < n; i++) c8Step(cpu);
  cpu.keypad[key] = 0;
}
function c8StartupDeep(cpu) { c8StartupHoldKey(cpu, 0, 150); }             // deep.py
function c8StartupVerticalBrix(cpu) { c8StartupHoldKey(cpu, 7, 1000); }    // vertical_brix.py
const C8_CUSTOM_STARTUP = { deep: c8StartupDeep, vertical_brix: c8StartupVerticalBrix };

function c8EnvRunStartup(env) {
  const cpu = env.cpu;
  c8Reset(cpu, 0, 0);                    // create_state(PRNGKey(0))
  c8LoadRom(cpu, env.rom);
  if (env.def.custom_startup) {
    const fn = C8_CUSTOM_STARTUP[env.def.custom_startup];
    if (!fn) throw new Error('no custom_startup transcribed for ' + env.def.custom_startup);
    fn(cpu);
  } else {
    for (let i = 0; i < env.def.startup_instructions; i++) c8Step(cpu);
  }
  env.startup = {
    mem: Uint8Array.from(cpu.mem), V: Uint8Array.from(cpu.V), I: cpu.I, pc: cpu.pc,
    stack: Uint16Array.from(cpu.stack), sp: cpu.sp, delay: cpu.delay, sound: cpu.sound,
    keypad: Uint8Array.from(cpu.keypad), display: Uint8Array.from(cpu.display),
  };
}

function c8EnvRestoreStartup(env) {
  const cpu = env.cpu, s = env.startup;
  cpu.mem.set(s.mem); cpu.V.set(s.V); cpu.I = s.I; cpu.pc = s.pc;
  cpu.stack.set(s.stack); cpu.sp = s.sp; cpu.delay = s.delay; cpu.sound = s.sound;
  cpu.keypad.set(s.keypad); cpu.display.set(s.display);
}

function c8Score(env) {
  return c8Eval(env.def.score, env.cpu).v;                  // * 1.0 in Octax: the same number
}

// OctaxEnv.reset(PRNGKey(seed)): the cached post-startup state with rng replaced.
function c8EnvReset(env, seed) {
  if (!env.startup) c8EnvRunStartup(env); else c8EnvRestoreStartup(env);
  env.cpu.rng[0] = 0; env.cpu.rng[1] = seed >>> 0;
  env.time = 0;
  env.score = c8Score(env); env.previousScore = env.score;
  env.reward = 0; env.terminated = false; env.truncated = false;
}

// OctaxEnv.step(state, action) -> reward
function c8EnvStep(env, action) {
  const cpu = env.cpu;
  const press = action !== env.noop;
  if (press) cpu.keypad[env.actionSet[action]] = 1;
  for (let i = 0; i < C8_INSTRUCTIONS_PER_ENV_STEP; i++) c8Step(cpu);
  if (env.disableDelay) { cpu.delay = 0; cpu.sound = 0; }
  else { cpu.delay = (cpu.delay - 1) & 0xFF; cpu.sound = (cpu.sound - 1) & 0xFF; }   // max(t - 1, 0) in uint8
  if (press) cpu.keypad[env.actionSet[action]] = 0;
  const current = c8Score(env);
  env.reward = current - env.previousScore;
  env.score = current; env.previousScore = current;
  env.time += 1;
  env.terminated = !!c8Eval(env.def.terminated, cpu).v;
  env.truncated = env.time >= env.maxSteps;
  return env.reward;
}

// ---- src/90_prelude.js ----
// ---- PlayTrain contract: setup / resetGame / draw / getGameState ----
// The bundle defines, before the sources:
//   C8_GAME_DEF : the games/<game>.json object (rom, action_set, startup, score, terminated, human)
//   C8_ROM_B64  : the ROM bytes, base64
// One draw() = one Octax env step (44 instructions). Observation = the display after the step,
// drawn with drawTiles as a 64x32 grid of two colours (Octax's `classic` scheme) letterboxed in a
// square canvas; at 64x64 observation resolution every CHIP-8 pixel is exactly one pixel.
// Octax's 4-frame stack and 8x scaling are not matched (manifest.json reference.not_matched).

// CHIP-8 keypad hex digit -> browser keyCode, conventional layout
//   1 2 3 C      1 2 3 4
//   4 5 6 D  ->  Q W E R
//   7 8 9 E      A S D F
//   A 0 B F      Z X C V
const C8_KEYCODES = [88, 49, 50, 51, 81, 87, 69, 65, 83, 68, 90, 67, 52, 82, 70, 86];
const C8_KEYNAMES = ['X', '1', '2', '3', 'Q', 'W', 'E', 'A', 'S', 'D', 'Z', 'C', '4', 'R', 'F', 'V'];

const C8_CANVAS = 256;                       // square; the display band is 256 x 128, centred
const C8_ON = [0, 255, 0], C8_OFF = [0, 0, 0];   // rendering.py create_color_scheme('classic')

// Integer-only base64 decoder (QuickJS has no atob).
const C8_B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
function c8B64Decode(s) {
  const lut = new Int16Array(128).fill(-1);
  for (let i = 0; i < 64; i++) lut[C8_B64.charCodeAt(i)] = i;
  let n = s.length; while (n > 0 && s.charCodeAt(n - 1) === 61) n--;      // '='
  const out = new Uint8Array(Math.floor(n * 3 / 4));
  let acc = 0, bits = 0, k = 0;
  for (let i = 0; i < n; i++) {
    const v = lut[s.charCodeAt(i)]; if (v < 0) continue;
    acc = ((acc << 6) | v) & 0xFFFFFF; bits += 6;
    if (bits >= 8) { bits -= 8; out[k++] = (acc >> bits) & 0xFF; }
  }
  return out.subarray(0, k);
}

let score = 0, lives = 1, gameState = 'PLAYING';
let c8Env = null;
const c8Kinds = new Uint16Array(C8_W * C8_H);
const c8Palette = new Uint8Array([C8_OFF[0], C8_OFF[1], C8_OFF[2], 255, C8_ON[0], C8_ON[1], C8_ON[2], 255]);

function c8Prepare() {
  if (c8Env) return;
  c8Env = c8EnvCreate(C8_GAME_DEF, c8B64Decode(C8_ROM_B64));
}

function setup() { c8Prepare(); createCanvas(C8_CANVAS, C8_CANVAS); }

function resetGame(seed) {
  c8Prepare();
  c8EnvReset(c8Env, seed >>> 0);
  score = c8Env.score; lives = 1; gameState = 'PLAYING';
}

// The action for this frame: the first held key in action_set order, else NOOP.
// Octax presses exactly one key per step; a human holding two gets the lower action index.
function c8ActionFromKeys() {
  const set = c8Env.actionSet;
  for (let i = 0; i < set.length; i++) if (keyIsDown(C8_KEYCODES[set[i]])) return i;
  return c8Env.noop;
}

function c8Render() {
  background(C8_OFF[0], C8_OFF[1], C8_OFF[2]);
  const d = c8Env.cpu.display;
  for (let x = 0; x < C8_W; x++) { const o = x * C8_H; for (let y = 0; y < C8_H; y++) c8Kinds[y * C8_W + x] = d[o + y]; }
  drawTiles(c8Kinds, C8_W, C8_H, c8Palette, 1, 2, 0, C8_CANVAS / 4, C8_CANVAS, C8_CANVAS / 2);
}

function draw() {
  if (!c8Env || c8Env.time === 0 && gameState !== 'PLAYING') resetGame(0);
  if (!c8Env.startup) resetGame(0);
  if (gameState === 'PLAYING') {
    c8EnvStep(c8Env, c8ActionFromKeys());
    score = c8Env.score;
    if (c8Env.terminated) gameState = 'GAMEOVER';
  }
  c8Render();
}

function getGameState() { return { score: score, lives: lives, gameState: gameState }; }

// gate hooks (node harnesses only)
globalThis.__chip8 = {
  reset: (seed) => { c8Prepare(); c8EnvReset(c8Env, seed >>> 0); score = c8Env.score; lives = 1; gameState = 'PLAYING'; },
  step: (a) => c8EnvStep(c8Env, a),
  env: () => c8Env,
  def: () => C8_GAME_DEF,
  snap: () => { const c = c8Env.cpu; return { t: c8Env.time, pc: c.pc, I: c.I, V: Array.from(c.V), sp: c.sp, stack: Array.from(c.stack), delay: c.delay, sound: c.sound, keypad: Array.from(c.keypad), display: c8DisplayHex(c), rng: Array.from(c.rng), score: c8Env.score, reward: c8Env.reward, terminated: c8Env.terminated, truncated: c8Env.truncated }; },
};
